#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXV = 10005;
const int S = MAXV - 2;
const int T = MAXV - 1;
const int MAXE = 2000000 + 10;
const int INF = 2000000000;

struct Edge {
    int to, nxt, cap, cost;
} edges[MAXE];

int head[MAXV], cnt = 1;
queue<int> q;
ll dist[MAXV];
bool mark[MAXV];

inline void add_edge(int u, int v, int cap, int cost) {
    edges[++cnt] = {v, head[u], cap, cost};
    head[u] = cnt;
    edges[++cnt] = {u, head[v], 0, -cost};
    head[v] = cnt;
}

inline bool spfa() {
    memset(mark, 0, sizeof(mark));
    memset(dist, 0x3f, sizeof(dist));
    q.push(T); dist[T] = 0; mark[T] = true;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        mark[x] = false;
        for (int i = head[x]; i; i = edges[i].nxt) {
            int y = edges[i].to;
            if (edges[i ^ 1].cap && dist[y] > dist[x] + edges[i ^ 1].cost) {
                dist[y] = dist[x] + edges[i ^ 1].cost;
                if (!mark[y]) { q.push(y); mark[y] = true; }
            }
        }
    }
    return dist[S] < 1e18;
}

inline int dfs(int x, int lim, ll &total) {
    int pushed = 0;
    mark[x] = true;
    if (x == T) return lim;
    for (int i = head[x]; i; i = edges[i].nxt) {
        int y = edges[i].to;
        if (!edges[i].cap || mark[y]) continue;
        if (dist[x] != dist[y] + edges[i].cost) continue;
        int t = dfs(y, min(edges[i].cap, lim - pushed), total);
        edges[i].cap -= t;
        edges[i ^ 1].cap += t;
        pushed += t;
        total += t * edges[i].cost;
        if (pushed == lim) return lim;
    }
    return pushed;
}

inline ll min_cost_flow() {
    int flow = 0;
    ll total = 0;
    while (spfa()) {
        do {
            memset(mark, 0, sizeof(mark));
            flow += dfs(S, INF, total);
        } while (mark[T]);
    }
    return total;
}

int main() {
    int n, m, k, c, d, lim = 101;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) { int x; cin >> x; --x; add_edge(S, x, 1, 0); }
    for (int i = 0; i < lim; i++) add_edge(i * n, T, k, c * i);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < lim - 1; j++)
            add_edge(i + j * n, i + (j + 1) * n, k, 0);
    while (m--) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < lim - 1; i++)
            for (int j = k - 1; j >= 0; j--) {
                add_edge(x + i * n, y + (i + 1) * n, 1, d * (j * 2 + 1));
                add_edge(y + i * n, x + (i + 1) * n, 1, d * (j * 2 + 1));
            }
    }
    cout << min_cost_flow();
    return 0;
}
